entries[56466] = { ["name"] = "Sonic Booster", ["text"] = "45 sec cast\nTools:\nBlacksmith Hammer\nReagents:\nFroststeel Tube (2), Overcharged Capacitor (4), Handful of Cobalt Bolts (2)\nSonic Booster\nBinds when equipped\nTrinket\n+81 Stamina\nRequires Engineering\n(390)\nEquip: The noise made from melee combat sometimes causes Sonic Awareness, increasing your attack power by 430 for 10 sec. This effect can only occur once every minute. (Proc chance: 35%, 50s cooldown)" }
